#!/usr/bin/env python3
from pathlib import Path
import base64, json, sys, zlib

_PACKED = ''
PAIRS = json.loads(zlib.decompress(base64.b64decode(_PACKED)).decode('utf-8'))

def transform(source: str, mode: str) -> str:
    if mode not in PAIRS:
        raise SystemExit(f"unknown transform mode: {mode}")
    for old64, new64 in PAIRS[mode]:
        old=base64.b64decode(old64).decode('utf-8')
        new=base64.b64decode(new64).decode('utf-8')
        count=source.count(old)
        if count != 1:
            raise SystemExit(f"{mode} session-mutation source contract drifted: anchor count={count}")
        source=source.replace(old,new,1)
    if mode == "unified":
        bad = 'for id in ["unified-kill-switch", "unified-multihop-toggle", "unified-mode-popup", "unified-dns-popup"] { self.findUnifiedView(id)?.isEnabled = !busy }'
        good = 'for id in ["unified-kill-switch", "unified-multihop-toggle", "unified-mode-popup", "unified-dns-popup"] { if let control = self.findUnifiedView(id) as? NSControl { control.isEnabled = !busy } }'
        count = source.count(bad)
        if count != 1:
            raise SystemExit(f"unified session-mutation control typing drifted: anchor count={count}")
        source = source.replace(bad, good, 1)
    return source

def main() -> None:
    if len(sys.argv) != 4:
        raise SystemExit('usage: macos-session-mutation-transform.py INPUT OUTPUT product|unified')
    src=Path(sys.argv[1]).read_text(encoding='utf-8')
    Path(sys.argv[2]).write_text(transform(src,sys.argv[3]),encoding='utf-8')

if __name__ == '__main__':
    main()
